                    </div>
                    <div style={{ fontSize: '10px', color: '#475569', marginTop: '4px' }}>
                      run {w.runLength}/{w.dominantN} · {Math.round(w.confidence * 100)}% conf
                    </div>
                  </>
                )}
              </div>
            </div>
          );
        })

